def choose_move(observation):
    def clamp(v):
        return -1 if v < -1 else (1 if v > 1 else v)

    def pos(v):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return None

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def get_list(*keys):
        for k in keys:
            v = observation.get(k)
            if v:
                return v
        return []

    def nearest(items, src):
        best = None
        best_d = None
        for it in items or []:
            p = pos(it)
            if p is None:
                continue
            d = manhattan(src, p)
            if best is None or d < best_d:
                best = p
                best_d = d
        return best, best_d

    def is_blocked(nx, ny):
        blocks = get_list("walls", "obstacles", "blocked_cells", "impassable")
        for b in blocks:
            p = pos(b)
            if p is not None and p[0] == nx and p[1] == ny:
                return True
        return False

    env = observation.get("environment_name", "") or ""
    role = observation.get("self_role", "") or ""
    self_pos = pos(observation.get("self_position")) or pos(observation.get("position")) or (0, 0)
    opp_pos = pos(observation.get("opponent_position")) or pos(observation.get("enemy_position")) or self_pos
    w = observation.get("grid_width", 0) or 0
    h = observation.get("grid_height", 0) or 0
    cx = w // 2 if w else 0
    cy = h // 2 if h else 0

    resources = get_list("resources", "resource_cells", "food", "collectibles")
    unclaimed = get_list("unclaimed_cells", "frontier", "target_cells", "opponent_territory", "neutral_cells")
    allies = get_list("team_positions", "ally_positions")

    def score_move(dx, dy):
        nx = self_pos[0] + dx
        ny = self_pos[1] + dy
        if w and (nx < 0 or nx >= w):
            return -10**9
        if h and (ny < 0 or ny >= h):
            return -10**9
        if is_blocked(nx, ny):
            return -10**9

        score = 0
        np = (nx, ny)

        if env == "pursuit_evasion":
            if role == "evader":
                d = manhattan(np, opp_pos)
                score += d * 12
                score += manhattan(np, (0, 0)) * 0
                if w and h:
                    score += min(nx, w - 1 - nx, ny, h - 1 - ny)
                if dx == 0 and dy == 0:
                    score -= 1
            else:
                d = manhattan(np, opp_pos)
                score += (20 - d) * 10
                if d == 0:
                    score += 100
        elif env == "territory_control":
            target, td = nearest(unclaimed, np)
            if target is None:
                target = (cx, cy)
                td = manhattan(np, target)
            score += (100 - td) * 8
            score += (manhattan(np, opp_pos) - manhattan(self_pos, opp_pos)) * 4
            if w and h:
                score += (min(nx, w - 1 - nx, ny, h - 1 - ny))
        else:
            target, td = nearest(resources, np)
            if target is not None:
                score += (100 - td) * 10
                if opp_pos != self_pos:
                    od = manhattan(opp_pos, target)
                    sd = manhattan(self_pos, target)
                    if od < sd:
                        score += 7
                    elif od == sd:
                        score += 2
            else:
                score += (100 - manhattan(np, (cx, cy))) * 2
            if allies:
                a, ad = nearest(allies, np)
                if a is not None and ad == 0:
                    score -= 2

        # small preference for staying put only when useful
        if dx == 0 and dy == 0:
            score -= 1
        return score

    best_move = [0, 0]
    best_score = None
    for dx in (-1, 0, 1):
        for dy in (-1, 0, 1):
            s = score_move(dx, dy)
            if best_score is None or s > best_score:
                best_score = s
                best_move = [dx, dy]

    return [clamp(best_move[0]), clamp(best_move[1])]

